import {colourMeta,colourCompare} from './wall.mjs';
export const normalise=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function hue(hex){if(!hex)return 1000;const [r,g,b]=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;if(d<.06)return 400+max;return ((max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60);}
export function filterPaints(paints,state){const terms=normalise(state.q).trim().split(/\s+/).filter(Boolean);return paints.filter(p=>(!state.brand||p.brand===state.brand)&&(!state.range||p.range===state.range)&&(!state.type||p.type===state.type)&&(!state.status||p.status===state.status)&&(!state.family||colourMeta(p).family===state.family)&&terms.every(t=>normalise([p.name,p.brand,p.range,p.code,p.type,...p.barcodes.map(b=>b.ean)].join(' ')).includes(t))).sort((a,b)=>{if(state.sort==='color'||state.sort==='hue')return colourCompare(a,b);if(state.sort==='brand'){const d=a.brand.localeCompare(b.brand)||String(a.range).localeCompare(String(b.range));if(d)return d;}if(state.sort==='code'){const d=String(a.code??'\uffff').localeCompare(String(b.code??'\uffff'),undefined,{numeric:true});if(d)return d;}return a.name.localeCompare(b.name)||a.brand.localeCompare(b.brand);});}
